SELECT * FROM (
    SELECT ROWNUM AS rnum, a.* FROM (
        SELECT *
        FROM REVIEW_TB
        WHERE SALES_POST_ID = #{salesPostId}
        ORDER BY CREATED_DATE DESC
    ) a
    WHERE ROWNUM <= #{offset} + #{limit}
)
WHERE rnum > #{offset}

SELECT COUNT(*)
FROM REVIEW_TB
WHERE SALES_POST_ID = #{salesPostId}

SELECT ID, REVIEW_ID, ORIGINAL_NAME, FILE_PATH, FILE_TYPE, UPLOAD_DATE
FROM REVIEW_FILE_TB
WHERE REVIEW_ID = #{reviewId}

SELECT ID, REVIEW_ID, ADMIN_ID, MESSAGE, CREATED_DATE, UPLOAD_DATE
FROM REVIEWS_REPLY_TB
WHERE REVIEW_ID = #{reviewId}

SELECT ID, USER_ID, SUBSTR(NICKNAME, 1, 4) || '****' AS NICKNAME, NAME, GENDER, PHONE, EMAIL, BIRTHDATE, ADDRESS, ADDRESS_DETAIL, ZIPCODE
FROM CUSTOMER_TB
WHERE ID = #{customerId}
